// Package difftool computes and renders unified diffs between two texts.
//
// It is intended to be used by testing tools that want to show a readable
// representation of how two pieces of text differ.
package difftool

import (
	"github.com/pmezard/go-difflib/difflib"
)

// DefaultContext is the number of unchanged lines shown around each change
// when Options.Context is left at its zero value.
const DefaultContext = 3

// Options controls how a unified diff is rendered.
type Options struct {
	// FromFile and ToFile are the labels printed in the --- and +++ headers.
	FromFile string
	ToFile   string
	// FromDate and ToDate are optional timestamps for the headers.
	FromDate string
	ToDate   string
	// Context is the number of unchanged lines surrounding each hunk.
	// A zero value selects DefaultContext.
	Context int
	// Eol is the line terminator used in the output. A zero value selects "\n".
	Eol string
}

// Unified returns a unified diff between texts a and b, using opts to control
// the output. The result is empty when the two texts are identical.
func Unified(a, b string, opts Options) (string, error) {
	context := opts.Context
	if context <= 0 {
		context = DefaultContext
	}
	eol := opts.Eol
	if eol == "" {
		eol = "\n"
	}

	return difflib.GetUnifiedDiffString(difflib.UnifiedDiff{
		A:        difflib.SplitLines(a),
		B:        difflib.SplitLines(b),
		FromFile: opts.FromFile,
		FromDate: opts.FromDate,
		ToFile:   opts.ToFile,
		ToDate:   opts.ToDate,
		Context:  context,
		Eol:      eol,
	})
}

// UnifiedText returns a unified diff between a and b using the default options
// and the labels "a" and "b".
func UnifiedText(a, b string) (string, error) {
	return Unified(a, b, Options{FromFile: "a", ToFile: "b"})
}

// Command difftool prints a unified diff between two files or streams.
//
// Usage:
//
//	difftool [flags] <from> <to>
//
// Use "-" in place of a path to read that side from standard input. The
// command exits with status 1 when the inputs differ, 0 when they are
// identical, and 2 on error, mirroring the traditional diff utility.
package main

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"os"

	"example.com/difftool"
)

func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintln(os.Stderr, "difftool:", err)
		os.Exit(2)
	}
}

func run(args []string) error {
	fs := flag.NewFlagSet("difftool", flag.ContinueOnError)
	var (
		context  = fs.Int("context", difftool.DefaultContext, "number of context lines around each change")
		fromName = fs.String("from", "", "label for the first input (defaults to its path)")
		toName   = fs.String("to", "", "label for the second input (defaults to its path)")
	)
	fs.Usage = func() {
		fmt.Fprintf(fs.Output(), "usage: difftool [flags] <from> <to>\n\n")
		fs.PrintDefaults()
	}
	if err := fs.Parse(args); err != nil {
		return err
	}
	if fs.NArg() != 2 {
		fs.Usage()
		return errors.New("expected exactly two inputs")
	}

	fromPath, toPath := fs.Arg(0), fs.Arg(1)
	from, err := readInput(fromPath)
	if err != nil {
		return err
	}
	to, err := readInput(toPath)
	if err != nil {
		return err
	}

	if *fromName == "" {
		*fromName = label(fromPath)
	}
	if *toName == "" {
		*toName = label(toPath)
	}

	out, err := difftool.Unified(string(from), string(to), difftool.Options{
		FromFile: *fromName,
		ToFile:   *toName,
		Context:  *context,
	})
	if err != nil {
		return err
	}

	if out == "" {
		return nil
	}
	if _, err := io.WriteString(os.Stdout, out); err != nil {
		return err
	}
	os.Exit(1)
	return nil
}

func readInput(path string) ([]byte, error) {
	if path == "-" {
		return io.ReadAll(os.Stdin)
	}
	return os.ReadFile(path)
}

func label(path string) string {
	if path == "-" {
		return "(stdin)"
	}
	return path
}

// Command difftool prints a unified diff between two files or streams.
//
// Usage:
//
//	difftool [flags] <from> <to>
//
// Use "-" in place of a path to read that side from standard input. The
// command exits with status 1 when the inputs differ, 0 when they are
// identical, and 2 on error, mirroring the traditional diff utility.
package main

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"os"

	"example.com/difftool"
)

func main() {
	os.Exit(run(os.Args[1:], os.Stdin, os.Stdout, os.Stderr))
}

// run executes the command and returns its process exit code.
func run(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	fs := flag.NewFlagSet("difftool", flag.ContinueOnError)
	fs.SetOutput(stderr)
	var (
		context  = fs.Int("context", difftool.DefaultContext, "number of context lines around each change")
		fromName = fs.String("from", "", "label for the first input (defaults to its path)")
		toName   = fs.String("to", "", "label for the second input (defaults to its path)")
	)
	fs.Usage = func() {
		fmt.Fprintf(fs.Output(), "usage: difftool [flags] <from> <to>\n\n")
		fs.PrintDefaults()
	}
	if err := fs.Parse(args); err != nil {
		return 2
	}
	if fs.NArg() != 2 {
		fs.Usage()
		fmt.Fprintln(stderr, "difftool: expected exactly two inputs")
		return 2
	}

	fromPath, toPath := fs.Arg(0), fs.Arg(1)
	from, err := readInput(fromPath, stdin)
	if err != nil {
		fmt.Fprintln(stderr, "difftool:", err)
		return 2
	}
	to, err := readInput(toPath, stdin)
	if err != nil {
		fmt.Fprintln(stderr, "difftool:", err)
		return 2
	}

	if *fromName == "" {
		*fromName = label(fromPath)
	}
	if *toName == "" {
		*toName = label(toPath)
	}

	out, err := difftool.Unified(string(from), string(to), difftool.Options{
		FromFile: *fromName,
		ToFile:   *toName,
		Context:  *context,
	})
	if err != nil {
		fmt.Fprintln(stderr, "difftool:", err)
		return 2
	}

	if out == "" {
		return 0
	}
	if _, err := io.WriteString(stdout, out); err != nil {
		fmt.Fprintln(stderr, "difftool:", err)
		return 2
	}
	return 1
}

func readInput(path string, stdin io.Reader) ([]byte, error) {
	if path == "-" {
		return io.ReadAll(stdin)
	}
	return os.ReadFile(path)
}

func label(path string) string {
	if path == "-" {
		return "(stdin)"
	}
	return path
}

var _ = errors.New

